/// Returns `true` if and only if for every index `i` in `arr`,
/// the value at `arr[i]` has the same parity as `i`.
/// That is, every even index contains an even number and
/// every odd index contains an odd number.
///
/// Examples:
///   is_odd_at_odd_index(&vec![])            == true
///   is_odd_at_odd_index(&vec![0, 1, 2, 3])  == true
///   is_odd_at_odd_index(&vec![2, 3, 4])     == false // index 1 has 3 (odd) – ok; index 2 has 4 (even) – ok; index 0 has 2 (even) – ok
///   is_odd_at_odd_index(&vec![2, 2, 4])     == false // index 1 has 2 (even)
fn is_odd_at_odd_index(arr: &Vec<usize>) -> bool {
    arr.iter()
       .enumerate()
       .all(|(i, &val)| (val % 2) == (i % 2))
}

